Visualization over groups - Set aesthetics
You can tell ggplot how to group data using aesthetics

The group=&lt;var&gt; aesthetic will create a new layer for each unique value of &lt;var&gt;
The color=&lt;var&gt; aesthetic will use a different color for observations depending on the value of &lt;var&gt;

Modify the previous visualization to add a color=Area aesthetic

Loading Datasets
First load the CRU and FAO data from Parquet Files

# Load required libraries
library(tidyverse)
library(arrow)
# Load the full fao dataset
read_parquet(
  file.path(data_path,"FAO","parquet","FAO_crop_livestock.parquet")
) |&gt;
  filter(Item == "Avocados" & Element == "Yield") -&gt; faostat_avocado

read_parquet(
  file.path(data_path,"CRU","parquet","tmp_w_ISO3.parquet")
) |&gt;
  filter(Period == "ANN") -&gt; cru_tmp_ann

faostat_avocado |&gt;
  inner_join(cru_tmp_ann,join_by(ISO3,Year),suffix=c("_fao","_cru")) |&gt;
  drop_na(ISO3) -&gt; avocado_tmp

Higher-order polynomials
You can construct higher order polynomials

R includes all orders of polynomials up to the highest level
y ~ x1*x1*x1 \begin{aligned}
y =& b_1 + b_1 x_1 + b_{11} x_1 x_1 + b_{111} x_1 x_1 x_1
\end{aligned}

Example:PG’s County July Temperatures
Let’s look at Prince George’s County (FIPS 26033) Temperatures


Code
read_parquet(file.path(data_path,"NOAA-NClimDiv","parquet","tmax.parquet")) |&gt;
  filter(StateCountyFIPS == "26033") |&gt;
  filter(Month == "Jul") |&gt;
  select(Year,Value) |&gt;
  rename(high_temp = Value) -&gt; tmax

read_parquet(file.path(data_path,"NOAA-NClimDiv","parquet","tmin.parquet")) |&gt;
  filter(StateCountyFIPS == "26033") |&gt;
  filter(Month == "Jul") |&gt;
  select(Year,Value) |&gt;
  rename(low_temp = Value) -&gt; tmin

tmax |&gt;
  full_join(tmin,join_by(Year)) -&gt; temps

ggplot(data=temps,mapping=aes(x=Year)) +
  geom_line(aes(y=high_temp,color="High"),linewidth=1.5) +
  geom_line(aes(y=low_temp,color="Low"),linewidth=1.5) +
  scale_color_manual(values=c("High"="red","Low"="blue")) +
  theme_bw() +
  labs(
    title="July Temperatures",
    subtitle="Prince George's County, MD",
    x="Year",
    y="Temperature (F)",
    color=""
  ) +
  theme(legend.position = "bottom")



